package org.sleepwell.app;
import android.content.*;import java.util.*;import org.json.*;
/** Atomic private profile/journal document, independent of main alarm schema and portable backup. */
final class NapProfilesStore {
 final SharedPreferences prefs;NapProfilesStore(Context c){prefs=c.getSharedPreferences("nap_profiles_v1",Context.MODE_PRIVATE);}
 static final class Data {final List<NapProfiles.Profile> profiles;final List<NapProfiles.Batch> batches;Data(List<NapProfiles.Profile> p,List<NapProfiles.Batch> b){profiles=List.copyOf(p);batches=List.copyOf(b);}}
 Data read(){synchronized(NapProfilesStore.class){try{String text=prefs.getString("document","");if(text.isEmpty())return new Data(List.of(),List.of());if(text.length()>1048576)throw new JSONException("Profile document too large");JSONObject root=new JSONObject(text);if(root.length()!=3||NapProfiles.number(root,"version")!=1)throw new JSONException("Unsupported profile document");JSONArray p=root.getJSONArray("profiles"),b=root.getJSONArray("batches");if(p.length()>20||b.length()>30)throw new JSONException("Too many saved profiles or applications");List<NapProfiles.Profile> profiles=new ArrayList<>();List<NapProfiles.Batch> batches=new ArrayList<>();Set<String> ids=new HashSet<>();for(int n=0;n<p.length();n++){NapProfiles.Profile item=NapProfiles.Profile.read(p.getJSONObject(n));if(!ids.add(item.id))throw new JSONException("Duplicate profile");profiles.add(item);}ids.clear();for(int n=0;n<b.length();n++){NapProfiles.Batch item=NapProfiles.Batch.read(b.getJSONObject(n));if(!ids.add(item.id))throw new JSONException("Duplicate profile application");batches.add(item);}return new Data(profiles,batches);}catch(JSONException|RuntimeException bad){throw new IllegalStateException("Saved nap profiles need attention. Their timers have not been changed.",bad);}}}
 private void write(Data data){try{JSONArray p=new JSONArray(),b=new JSONArray();for(NapProfiles.Profile value:data.profiles)p.put(value.json());for(NapProfiles.Batch value:data.batches)b.put(value.json());String text=new JSONObject().put("version",1).put("profiles",p).put("batches",b).toString();if(text.length()>1048576||!prefs.edit().putString("document",text).commit())throw new IllegalStateException("Nap profiles could not be saved.");}catch(JSONException impossible){throw new IllegalStateException(impossible);}}
 NapProfiles.Profile profile(String id){for(NapProfiles.Profile p:read().profiles)if(p.id.equals(id))return p;throw new IllegalArgumentException("This profile was removed.");}
 NapProfiles.Batch batch(String id){for(NapProfiles.Batch b:read().batches)if(b.id.equals(id))return b;throw new IllegalArgumentException("This application relation was removed.");}
 NapProfiles.Profile save(NapProfiles.Profile draft){synchronized(NapProfilesStore.class){Data data=read();List<NapProfiles.Profile> values=new ArrayList<>(data.profiles);int index=-1;for(int n=0;n<values.size();n++)if(values.get(n).id.equals(draft.id))index=n;if(index<0&&draft.revision!=0||index>=0&&values.get(index).revision!=draft.revision)throw new IllegalArgumentException("This profile changed. Reopen it before saving.");if(index<0&&values.size()>=20)throw new IllegalArgumentException("Save up to 20 profiles. Remove one before adding another.");if(draft.revision==Integer.MAX_VALUE)throw new IllegalArgumentException("Profile revision limit reached.");NapProfiles.Profile saved=new NapProfiles.Profile(draft.id,draft.name,draft.revision+1,draft.entries,draft.weekly,draft.weekdays);if(index<0)values.add(saved);else values.set(index,saved);write(new Data(values,data.batches));return saved;}}
 void removeProfile(String id,int revision){synchronized(NapProfilesStore.class){Data data=read();List<NapProfiles.Profile> values=new ArrayList<>(data.profiles);NapProfiles.Profile current=profile(id);if(current.revision!=revision)throw new IllegalArgumentException("Profile changed. Reopen it.");values.removeIf(p->p.id.equals(id));write(new Data(values,data.batches));}}
 void put(NapProfiles.Batch batch){synchronized(NapProfilesStore.class){Data data=read();List<NapProfiles.Batch> values=new ArrayList<>(data.batches);int index=-1;for(int n=0;n<values.size();n++)if(values.get(n).id.equals(batch.id))index=n;if(index<0){if(values.size()>=30)throw new IllegalArgumentException("Remove an old application relation before applying another profile.");values.add(batch);}else values.set(index,batch);write(new Data(data.profiles,values));}}
 int mergeDefinitions(NapProfilesDefinitions.Plan reviewed){synchronized(NapProfilesStore.class){Data data=read();if(!NapProfilesDefinitions.snapshot(data.profiles).equals(reviewed.snapshot))throw new IllegalArgumentException("Saved profile definitions changed. Refresh the import review before merging.");NapProfilesDefinitions.Plan current=new NapProfilesDefinitions.Plan(reviewed.incoming,data.profiles);if(!current.fits())throw new IllegalArgumentException("The whole merge would exceed 20 profiles. Remove definitions or choose a smaller document; nothing was imported.");List<NapProfiles.Profile> values=new ArrayList<>(data.profiles);Set<String> ids=new HashSet<>();for(NapProfiles.Profile p:values)ids.add(p.id);for(NapProfilesDefinitions.Definition d:current.additions){String id;do{id=UUID.randomUUID().toString();}while(!ids.add(id));values.add(new NapProfiles.Profile(id,d.name,1,d.entries,d.weekly,d.weekdays));}if(!current.additions.isEmpty())write(new Data(values,data.batches));return current.additions.size();}}
 void detach(String id){synchronized(NapProfilesStore.class){Data data=read();List<NapProfiles.Batch> values=new ArrayList<>(data.batches);values.removeIf(b->b.id.equals(id));write(new Data(data.profiles,values));}}
}
